-- 常年會費欠繳名單 (來源: To 仲阜 會員名單及繳費情況(814).xlsx)
-- 一次性匯入，不提供後台上傳介面。id_card 為報名時的比對 key。
--
-- 本版改為「分年記錄」: due_113 / due_114 / due_115 三個欄位為唯一真實來源，
-- 應繳總額一律由三年相加得出，程式不再讀取 total_due。
-- total_due 保留為學會提供的加總值，僅供人工對帳，請勿在程式中使用。
--
-- 年度費率 (取自 Excel 欄位標題):
--   113年 正式會員 $2000 / 準會員 $500
--   114年 正式會員 $2000 / 準會員 $500
--   115年 正式會員 $3000 / 準會員 $500
--
-- 本檔取代舊版 membership_fee_due_20260814.sql，會先 DROP 再重建，可重複執行。
--
-- ── 匯入時對原始資料做的唯一修正 ─────────────────────────────
-- Excel 中下列兩筆的身分證首字母為「全形」英文字母，已轉為半形。
-- 不轉的話，報名時使用者輸入半形字母永遠比對不到，會被當成無欠費而少收錢。
--   編號 201 徐維澤  Ｄ122059654 -> D122059654
--   編號 403 林元培  Ｎ124053694 -> N124053694
-- 其餘欄位一律原樣匯入，未做任何加工。
-- ─────────────────────────────────────────────────────────
--
-- 本檔為 UTF-8 編碼。Windows 上的 mysql client 預設以系統 ANSI (cp950) 宣告
-- character_set_client，會把中文姓名判成 ERROR 1366，故在此明確指定連線編碼。
SET NAMES utf8mb4;

DROP TABLE IF EXISTS membership_fee_due;

CREATE TABLE membership_fee_due (
  membership_fee_due_id BIGINT        NOT NULL COMMENT '主鍵ID',
  id_card               VARCHAR(32)   DEFAULT NULL COMMENT '身分證字號,與 member.id_card 比對',
  member_no             VARCHAR(32)   DEFAULT NULL COMMENT '學會會員編號,供人工核對',
  chinese_name          VARCHAR(64)   DEFAULT NULL COMMENT '中文姓名',
  member_category       VARCHAR(32)   DEFAULT NULL COMMENT '會員類別:正式會員/準會員/榮譽會員',
  due_113               DECIMAL(10,2) NOT NULL DEFAULT 0 COMMENT '113年度應補繳常年會費',
  due_114               DECIMAL(10,2) NOT NULL DEFAULT 0 COMMENT '114年度應補繳常年會費',
  due_115               DECIMAL(10,2) NOT NULL DEFAULT 0 COMMENT '115年度應補繳常年會費',
  total_due             DECIMAL(10,2) NOT NULL DEFAULT 0 COMMENT '學會提供的加總值,僅供對帳,程式請改用三個年度欄位相加',
  create_by             VARCHAR(64)   DEFAULT NULL COMMENT '創建者',
  create_date           DATETIME      DEFAULT NULL COMMENT '創建時間',
  update_by             VARCHAR(64)   DEFAULT NULL COMMENT '最後修改者',
  update_date           DATETIME      DEFAULT NULL COMMENT '最後修改時間',
  is_deleted            TINYINT       NOT NULL DEFAULT 0 COMMENT '邏輯刪除,0活躍 1刪除',
  PRIMARY KEY (membership_fee_due_id),
  UNIQUE KEY uk_membership_fee_due_id_card (id_card)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='常年會費欠繳名單';

