-- ============================================================
-- 匯入後驗證，三段查詢都必須符合預期，否則代表匯入錯行
-- ============================================================

-- 1. 總筆數應為 465
SELECT COUNT(*) AS total_rows FROM membership_fee_due;

-- 2. 三個年度相加與學會加總值不符者，應為 0 筆
SELECT membership_fee_due_id, member_no, chinese_name,
       due_113, due_114, due_115, total_due
FROM membership_fee_due
WHERE due_113 + due_114 + due_115 <> total_due;

-- 3. 各年度合計應為 113年 116500 / 114年 168000 / 115年 1170000 / 總計 1454500
SELECT SUM(due_113) AS sum_113,
       SUM(due_114) AS sum_114,
       SUM(due_115) AS sum_115,
       SUM(due_113 + due_114 + due_115) AS sum_all,
       SUM(total_due) AS sum_total_due
FROM membership_fee_due;

